B.Rw=new A.L("Warehouse Management System","\u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u0628\u0627\u0631")
B.Sl=new A.L("Multi-warehouse inventory system with role-based access, barcode/Excel intake, outbound tracking, and stock reports.","\u0633\u06cc\u0633\u062a\u0645 \u0645\u0648\u062c\u0648\u062f\u06cc \u0686\u0646\u062f\u0627\u0646\u0628\u0627\u0631\u0647 \u0628\u0627 \u062f\u0633\u062a\u0631\u0633\u06cc \u0646\u0642\u0634\u200c\u0645\u062d\u0648\u0631\u060c \u0648\u0631\u0648\u062f \u0628\u0627\u0631\u06a9\u062f/Excel\u060c \u0631\u0647\u06af\u06cc\u0631\u06cc \u062e\u0631\u0648\u062c \u0648 \u06af\u0632\u0627\u0631\u0634 \u0645\u0648\u062c\u0648\u062f\u06cc.")
B.TC=new A.L("Business Management System","\u0633\u06cc\u0633\u062a\u0645 \u0645\u062f\u06cc\u0631\u06cc\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631")
B.a2c=s(["Django","REST API","Electron.js","MySQL"],t.s)
B.Sf=new A.L("A warehouse management platform with Django REST API and an Electron desktop client for daily operations. Supports multi-warehouse setup, role-based permissions, three product intake methods (manual, barcode scan, Excel import), outbound workflows for field experts and customers, return registration, and flexible stock and movement reports.","\u067e\u0644\u062a\u0641\u0631\u0645 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u0628\u0627\u0631 \u0628\u0627 Django REST API \u0648 \u06a9\u0644\u0627\u06cc\u0646\u062a Electron. \u0686\u0646\u062f \u0627\u0646\u0628\u0627\u0631\u060c \u062f\u0633\u062a\u0631\u0633\u06cc \u0646\u0642\u0634\u200c\u0645\u062d\u0648\u0631\u060c \u0648\u0631\u0648\u062f \u062f\u0633\u062a\u06cc/\u0628\u0627\u0631\u06a9\u062f/Excel\u060c \u06af\u0631\u062f\u0634 \u062e\u0631\u0648\u062c \u0648 \u0645\u0631\u062c\u0648\u0639\u06cc \u0648 \u06af\u0632\u0627\u0631\u0634 \u0627\u0646\u0639\u0637\u0627\u0641\u200c\u067e\u0630\u06cc\u0631.")
B.TH=new A.L("The business managed warehouse stock in spreadsheets. Counts did not match reality, there was no barcode workflow, team permissions were unclear, and managers had no unified view of inbound, outbound, and return movements.","\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u0628\u0627\u0631 \u0628\u0627 Excel \u0628\u0627\u0639\u062b \u0645\u063a\u0627\u06cc\u0631\u062a \u0645\u0648\u062c\u0648\u062f\u06cc\u060c \u0646\u0628\u0648\u062f \u0628\u0627\u0631\u06a9\u062f\u060c \u0645\u062c\u0648\u0632\u0647\u0627\u06cc \u0646\u0627\u0645\u0634\u062e\u0635 \u0648 \u0646\u0628\u0648\u062f \u062f\u06cc\u062f \u06cc\u06a9\u067e\u0627\u0631\u0686\u0647 \u0627\u0632 \u06af\u0631\u062f\u0634 \u06a9\u0627\u0644\u0627 \u0645\u06cc\u200c\u0634\u062f.")
B.RN=new A.L("Developed Django REST API with role-based access control, Electron desktop UI, triple intake modes (manual, barcode, Excel bulk import), outbound and return workflows, configurable user/warehouse limits, and reporting by stock, date range, and movement type.","REST API \u0628\u0627 \u06a9\u0646\u062a\u0631\u0644 \u062f\u0633\u062a\u0631\u0633\u06cc\u060c UI Electron\u060c \u0633\u0647 \u0631\u0648\u0634 \u0648\u0631\u0648\u062f\u060c \u06af\u0631\u062f\u0634 \u062e\u0631\u0648\u062c \u0648 \u0645\u0631\u062c\u0648\u0639\u06cc\u060c \u0633\u0642\u0641 \u06a9\u0627\u0631\u0628\u0631/\u0627\u0646\u0628\u0627\u0631 \u0648 \u06af\u0632\u0627\u0631\u0634\u200c\u06af\u06cc\u0631\u06cc.")
B.SP=new A.L("Accurate real-time inventory across warehouses. Faster intake via barcode and Excel. Controlled access per role. Actionable reports replaced manual stock reconciliation.","\u0645\u0648\u062c\u0648\u062f\u06cc \u0644\u062d\u0638\u0647\u200c\u0627\u06cc \u062f\u0642\u06cc\u0642. \u0648\u0631\u0648\u062f \u0633\u0631\u06cc\u0639\u200c\u062a\u0631. \u062f\u0633\u062a\u0631\u0633\u06cc \u06a9\u0646\u062a\u0631\u0644\u200c\u0634\u062f\u0647. \u06af\u0632\u0627\u0631\u0634\u200c\u0647\u0627\u06cc \u0639\u0645\u0644\u06cc\u0627\u062a\u06cc \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u062a\u0637\u0628\u06cc\u0642 \u062f\u0633\u062a\u06cc.")
